local context = require "wa.context"
local events = require "wa.events"
local items = require "wa.items"

local R = require "core.lib.rathena"
local KNIFE = items.id "Knife"
local JELLOPY = items.id "Jellopy"
local MARVELOUS_MEDAL = items.id "Marvelous_Medal"

return function()
  local npc = context:get_instance()
  events.on("click", function(player, conversation)
    R.run(function()
      local pm, total_pm, i, menu, m, items_, item_array, m2 = {}, 0, 0, "", 0, "", {}, 0
      if (not player:can_carry(KNIFE, 1)) then
        conversation:say("[Wayne]", "Hold on a second...", "If you want to exchange", "your Prize Medals for items,", "you'd better free up more space", "in your Inventory first. Why don't you use your Kafra Storage?")
        do return end
      end
      conversation:say("[Wayne]", "Hello, there! Ever wonder", "what you could do with all", "the Prize Medals you can win", "in Monster Race Arena? You", "can donate them in Einbroch", "to the Blacksmith Guild...")
      conversation:wait_for_next()
      conversation:say("[Wayne]", "...Or you can exchange them", "for items, right here and right", "now, with me. As always, the", "choice is really up to you.")
      conversation:wait_for_next()
      if (conversation:choose("Prize Medal Exchange", "Cancel") == 2) then
        conversation:say("[Wayne]", "Well, just keep in mind", "that you can always come", "to me to trade in your Prize", "Medals for consumable items.", "That guy in Einbroch? Not sure", "what he'd give you for them...")
        conversation:wait_for_next()
        conversation:say("[Wayne]", "All I know is that he", "needs a whole lot of medals", "for the work that he's doing.", "Still, I hear that he just may", "make your donations worth", "all your effort, you know?")
        do return end
      end
      if (not player:can_carry(JELLOPY, 550)) then
        conversation:say("[Wayne]", "Hold on a second...", "If you want to exchange", "your Prize Medals for items,", "you'd better free up more space", "in your Inventory first. Why don't you use your Kafra Storage?")
        do return end
      else
        conversation:say("[Wayne]", "Now, how many Prize Medals", "would you like to exchange?", "It doesn't take a genius to", "figure out that you can get", "more valuable items by trading", "more Prize Medals at a time.")
        conversation:wait_for_next()
        R.setarray(pm, 0, 1, 3, 7, 8, 16, 25, 42, 59)
        total_pm = R.size(pm)
        i = 0
        while (i < total_pm) do
          menu = menu .. (pm[i] or 0) .. " Prize medal:"
          i = (i + 1)
        end
        m = (conversation:choose(R.menu(menu)) - 1)
        do
          local value_2 = m
          if value_2 == 0 then goto case_4
          elseif value_2 == 1 then goto case_5
          elseif value_2 == 2 then goto case_6
          elseif value_2 == 3 then goto case_7
          elseif value_2 == 4 then goto case_8
          elseif value_2 == 5 then goto case_9
          elseif value_2 == 6 then goto case_10
          elseif value_2 == 7 then goto case_11
          end
          goto switch_end_3
          ::case_4::
          items_ = "2 Hinale Leaflets:2 Aloe Leaflets:1 Mastela Fruit:5 Witch Starsands:4 Condensed Red Potions"
          R.setarray(item_array, 0, 520, 2, 521, 2, 522, 1, 1061, 5, 545, 4)
          goto switch_end_3
          ::case_5::
          items_ = "1 Royal Jelly:6 Holy Waters"
          R.setarray(item_array, 0, 526, 1, 523, 6)
          goto switch_end_3
          ::case_6::
          items_ = "1 Cookie Bag:1 First Aid Kit"
          R.setarray(item_array, 0, 12130, 1, 12110, 1)
          goto switch_end_3
          ::case_7::
          items_ = "1 Gift Box"
          R.setarray(item_array, 0, 644, 1)
          goto switch_end_3
          ::case_8::
          items_ = "1 Old Blue Box"
          R.setarray(item_array, 0, 603, 1)
          goto switch_end_3
          ::case_9::
          items_ = "1 Taming Gift Set"
          R.setarray(item_array, 0, 12105, 1)
          goto switch_end_3
          ::case_10::
          items_ = "1 Old Purple Box"
          R.setarray(item_array, 0, 617, 1)
          goto switch_end_3
          ::case_11::
          items_ = "1 Poring Box"
          R.setarray(item_array, 0, 12109, 1)
          goto switch_end_3
          ::switch_end_3::
        end
        conversation:say("[Wayne]", "Now, please choose", "which of the following item", "sets that you'd like to receive", "in exchange for " .. (pm[m] or 0) .. " Prize Medal." .. ((R.size(item_array) < 3) and " Well, we have only 1 set, but..." or ""))
        conversation:wait_for_next()
        m2 = ((conversation:choose(R.menu(items_)) - 1) * 2)
        if (player:count_item(MARVELOUS_MEDAL) < (pm[m] or 0)) then
          conversation:say("[Wayne]", "Hey, you don't have", "enough Prize Medals with", "you. Go and get some more", "if you want to exchange", "them with me for anything.")
          do return end
        end
        conversation:say("[Wayne]", "There you go~", "Thanks for using my", "service, and I hope that", "you come visit me again", "soon. Enjoy the monster", "races, fair adventurer~")
        R.take_item(player, MARVELOUS_MEDAL, (pm[m] or 0))
        R.give_item(player, (item_array[m2] or 0), (item_array[(m2 + 1)] or 0))
        do return end
      end
    end)
  end)
end
